(function(root){
// Whole-word IPA cards: say the word represented by the transcription.
const IPA=[['/kæt/','CAT'],['/dɒɡ/','DOG'],['/bʊk/','BOOK'],['/pen/','PEN'],['/sʌn/','SUN'],['/muːn/','MOON'],['/fɪʃ/','FISH'],['/triː/','TREE'],['/red/','RED'],['/bluː/','BLUE'],['/ɡriːn/','GREEN'],['/hæt/','HAT'],['/bæɡ/','BAG'],['/bʌs/','BUS'],['/kɑː/','CAR'],['/miːt/','MEET'],['/ʃiːp/','SHEEP'],['/tʃeə/','CHAIR'],['/dʒuːs/','JUICE'],['/θɪŋk/','THINK'],['/ðɪs/','THIS'],['/ˈæpəl/','APPLE'],['/ˈtiːtʃə/','TEACHER'],['/ˈwɔːtə/','WATER'],['/ˈwɪndəʊ/','WINDOW'],['/ˈpæspɔːt/','PASSPORT'],['/ˈlɪsən/','LISTEN'],['/ˈsɪstə/','SISTER'],['/ˈbrekfəst/','BREAKFAST'],['/ˈelɪfənt/','ELEPHANT']].map(([prompt,answer],i)=>({id:`ipa-${i}`,kind:'ipa',mode:'ipa',level:i<15?1:2,prompt,answer,spoken:answer,topic:'British English word transcription',hint:'Say the word represented by the transcription.'}));
function numberPool(max=1000){return Array.from({length:max+1},(_,n)=>({id:`number-${n}`,kind:'numbers',mode:'numbers',level:n<=20?1:n<=100?2:3,prompt:root.numberToWords(n),answer:String(n),spoken:root.numberToWords(n),topic:'Whole numbers 0–'+max}));}
function poolFor(config,custom=[]){if(!['type','voice'].includes(config.control))return[];const level=Number(config.level||2),bank=[...root.QUESTION_BANK,...custom];const numbers=()=>numberPool(Number(config.range||100));const letters=()=>config.control==='voice'?Array.from('ABCDEFGHIJKLMNOPQRSTUVWXYZ').map(c=>({id:`letter-${c}`,kind:'letters',mode:'letters',level:1,prompt:c,answer:c,spoken:c,topic:'Letter names'})):[];const vocab=()=>bank.filter(q=>q.mode==='vocabulary'&&q.level<=level).map(q=>({...q,kind:'words',spoken:q.answer}));const spelling=()=>bank.filter(q=>q.mode==='spelling'&&q.level<=level&&/^[A-Z]+$/.test(q.answer)).map(q=>({...q,kind:'spelling',prompt:q.answer,spoken:q.answer}));const pools={numbers,letters,words:vocab,spelling,mixed:()=>[...numbers(),...letters(),...vocab()],ipa:()=>IPA};const pool=(pools[config.skill]||numbers)();return pool.map(q=>({...q,display:config.control==='voice'?(q.kind==='ipa'?q.prompt:q.answer):q.prompt}));}
root.InkContent={IPA,numberPool,poolFor};if(typeof module!=='undefined')module.exports=root.InkContent;
})(typeof window!=='undefined'?window:globalThis);
